function writeBinary(repoPath, sha, b64) {
  // §250: binary asset, sha256 = marker (no text marker fits an image).
  try {
    const crypto = require("crypto");
    const hash = (buf) => crypto.createHash("sha256").update(buf).digest("hex");
    const data = Buffer.from(b64, "base64");
    if (hash(data) !== sha) throw new Error("embedded copy is corrupt");
    let backup = null;
    if (fs.existsSync(repoPath)) {
      if (hash(fs.readFileSync(repoPath)) === sha) {
        console.log("= " + repoPath + " (already correct)");
        already++;
        return;
      }
      backup = repoPath + BACKUP_TAG;
      if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
    } else {
      const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
      if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    }
    fs.writeFileSync(repoPath, data);
    if (hash(fs.readFileSync(repoPath)) !== sha) {
      if (backup) fs.copyFileSync(backup, repoPath);
      else fs.unlinkSync(repoPath);
      throw new Error("written bytes do not verify" + (backup ? " - old copy restored" : ""));
    }
    console.log("+ " + repoPath + (backup ? " (REPAIRED - old copy kept as " + BACKUP_TAG + ")" : " (new file)"));
    applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
